/**
 * SES — savoir-faire quantitatifs (EC2). All data are FICTIONAL
 * ("Pays A", "Entreprise B"…), generated by code.
 */
import type { Rng } from '../../lib/rng';
import { defineGenerator } from '../define';
import { m, num, numericMcq, buildMcq } from '../helpers';
import type { AnswerSpec, Figure, Format } from '../types';

const nf = (x: number, d = 1) => num(Math.round(x * 10 ** d) / 10 ** d, 'fr');
const SKILL = 'ses-calc';

interface Series {
  entity: string;
  variable: string;
  unit: string;
}

const SERIES: Series[] = [
  { entity: 'Pays A', variable: 'PIB', unit: 'en milliards d’euros' },
  { entity: 'Pays B', variable: 'Population active', unit: 'en millions' },
  { entity: 'Entreprise B', variable: 'Chiffre d’affaires', unit: 'en millions d’euros' },
  { entity: 'Région C', variable: 'Nombre d’emplois', unit: 'en milliers' },
  { entity: 'Pays D', variable: 'Émissions de CO₂', unit: 'en millions de tonnes' },
  { entity: 'Entreprise E', variable: 'Nombre de salariés', unit: 'en unités' },
];

const YEARS = [2010, 2015, 2018, 2020, 2022, 2024];

function pickYears(rng: Rng): [number, number] {
  const a = rng.int(0, YEARS.length - 2);
  const b = rng.int(a + 1, YEARS.length - 1);
  return [YEARS[a], YEARS[b]];
}

function valueTable(s: Series, years: number[], values: number[]): Figure {
  return {
    kind: 'table',
    caption: `${s.variable} — ${s.entity} (${s.unit}) — données fictives`,
    headers: ['Année', ...years.map(String)],
    rows: [[s.variable, ...values.map((v) => `$${num(v, 'fr')}$`)]],
  };
}

/** numeric answer for SES: input (rounded) or MCQ with typical mistakes */
function sesAnswer(rng: Rng, f: Format, value: number, decimals: number, distractors: { v: number; e?: 'calcul' | 'methode' | 'cours' | 'lecture' }[], suffix = ''): { answer: AnswerSpec; answerDisplay: string } {
  const shown = `${nf(value, decimals)}${suffix}`;
  if (f === 'mcq') {
    return {
      answer: numericMcq(rng, Math.round(value * 10 ** decimals) / 10 ** decimals, distractors.map((d) => ({ v: Math.round(d.v * 10 ** decimals) / 10 ** decimals, e: d.e })), (x) => m(`${nf(x, decimals)}${suffix}`), { integer: false, spread: Math.max(1, Math.abs(value) * 0.2) }),
      answerDisplay: m(shown),
    };
  }
  return { answer: { kind: 'number', value, tolerance: 0.5 * 10 ** -decimals + 1e-9 }, answerDisplay: m(shown) };
}

const roundHint = (d: number) => (d === 0 ? 'Arrondis à l’unité.' : d === 1 ? 'Arrondis au dixième.' : 'Arrondis au centième.');

// ---------------------------------------------------------------- taux de variation / coefficient multiplicateur
export const tauxVariation = defineGenerator({
  id: 'ses-taux-variation',
  subject: 'ses',
  skill: SKILL,
  title: 'Taux de variation et coefficient multiplicateur',
  formats: ['input', 'mcq'],
  difficulties: ['easy', 'medium', 'hard'],
  targetSec: 90,
  build(rng, d, f) {
    const s = rng.pick(SERIES);
    const [y1, y2] = pickYears(rng);
    const v1 = rng.int(50, 900);
    const ratio = d === 'easy' ? 1 + rng.int(-30, 60) / 100 : 0.6 + rng.next() * 1.4;
    const v2 = Math.max(1, Math.round(v1 * ratio * (d === 'hard' ? 10 : 1)) / (d === 'hard' ? 10 : 1));
    const fig = valueTable(s, [y1, y2], [v1, v2]);
    const askCm = d !== 'easy' && rng.bool(0.4);
    if (askCm) {
      const cm = v2 / v1;
      return {
        prompt: `À l’aide du tableau (données fictives), calcule le coefficient multiplicateur de la variable « ${s.variable} » entre ${y1} et ${y2}. ${roundHint(2)}`,
        figure: fig,
        ...sesAnswer(rng, f, cm, 2, [
          { v: v1 / v2, e: 'methode' },
          { v: cm - 1, e: 'cours' },
          { v: (cm - 1) * 100, e: 'cours' },
        ]),
        hints: ['Coefficient multiplicateur = valeur d’arrivée ÷ valeur de départ.', `Valeur de départ (${y1}) : ${m(nf(v1, 2))}.`],
        solution: [`${m(`\\text{CM} = \\frac{${nf(v2, 2)}}{${nf(v1, 2)}}`)}.`, `${m(`\\text{CM} \\approx ${nf(cm, 2)}`)}.`, `Entre ${y1} et ${y2}, la variable a été multipliée par ${m(nf(cm, 2))} (données fictives).`],
        meta: { kind: 'cm', v1, v2, value: cm },
      };
    }
    const t = ((v2 - v1) / v1) * 100;
    return {
      prompt: `À l’aide du tableau (données fictives), calcule le taux de variation de la variable « ${s.variable} » entre ${y1} et ${y2}, en %. ${roundHint(1)}`,
      figure: fig,
      ...sesAnswer(
        rng,
        f,
        t,
        1,
        [
          { v: ((v2 - v1) / v2) * 100, e: 'methode' },
          { v: v2 - v1, e: 'cours' },
          { v: (v2 / v1) * 100, e: 'cours' },
        ],
        ' \\%',
      ),
      hints: ['Taux de variation = (valeur d’arrivée − valeur de départ) ÷ valeur de départ × 100.', `Valeur de départ : celle de ${y1}, soit ${m(nf(v1, 2))}.`],
      solution: [`${m(`\\frac{${nf(v2, 2)} - ${nf(v1, 2)}}{${nf(v1, 2)}} \\times 100`)}.`, `${m(`\\approx ${nf(t, 1)}\\ \\%`)}.`, `Entre ${y1} et ${y2}, la variable a ${t >= 0 ? 'augmenté' : 'diminué'} de ${m(`${nf(Math.abs(t), 1)}\\ \\%`)} (données fictives).`],
      meta: { kind: 'tv', v1, v2, value: t },
    };
  },
});

// ---------------------------------------------------------------- indice base 100
export const indice100 = defineGenerator({
  id: 'ses-indice',
  subject: 'ses',
  skill: SKILL,
  title: 'Indice base 100',
  formats: ['input', 'mcq'],
  difficulties: ['easy', 'medium', 'hard'],
  targetSec: 100,
  build(rng, d, f) {
    const s = rng.pick(SERIES);
    const years = [...YEARS].slice(0, 4 + rng.int(0, 2));
    const values: number[] = [];
    let v = rng.int(80, 600);
    for (let i = 0; i < years.length; i++) {
      values.push(v);
      v = Math.round(v * (0.85 + rng.next() * 0.35));
    }
    const ref = rng.int(0, years.length - 2);
    const tgt = rng.pick(years.map((_, i) => i).filter((i) => i !== ref));
    const idx = (values[tgt] / values[ref]) * 100;
    if (d === 'hard') {
      // reading indices: from two indices, compute the variation between two non-reference years
      const a = rng.pick(years.map((_, i) => i).filter((i) => i !== ref));
      let b = rng.pick(years.map((_, i) => i).filter((i) => i !== ref && i !== a));
      if (b < a) b = a;
      const ia = Math.round((values[a] / values[ref]) * 1000) / 10;
      const ib = Math.round((values[b] / values[ref]) * 1000) / 10;
      const [i1, i2, y1, y2] = a < b ? [ia, ib, years[a], years[b]] : [ib, ia, years[b], years[a]];
      const t = ((i2 - i1) / i1) * 100;
      return {
        prompt: `Dans un document (données fictives), la variable « ${s.variable} » de ${s.entity} a pour indice ${m(nf(i1, 1))} en ${y1} et ${m(nf(i2, 1))} en ${y2} (base 100 en ${years[ref]}). Calcule le taux de variation entre ${y1} et ${y2}, en %. ${roundHint(1)}`,
        ...sesAnswer(
          rng,
          f,
          t,
          1,
          [
            { v: i2 - i1, e: 'cours' },
            { v: i2 - 100, e: 'methode' },
            { v: ((i2 - i1) / i2) * 100, e: 'methode' },
          ],
          ' \\%',
        ),
        hints: ['On peut calculer un taux de variation directement à partir des indices (comme avec les valeurs).', `Attention : ${m(`${nf(i2, 1)} - ${nf(i1, 1)}`)} est une différence en points d’indice, pas un pourcentage.`],
        solution: [`${m(`\\frac{${nf(i2, 1)} - ${nf(i1, 1)}}{${nf(i1, 1)}} \\times 100`)}.`, `${m(`\\approx ${nf(t, 1)}\\ \\%`)}.`, `Entre ${y1} et ${y2}, la variable a ${t >= 0 ? 'augmenté' : 'diminué'} de ${m(`${nf(Math.abs(t), 1)}\\ \\%`)}.`],
        meta: { kind: 'index-variation', i1, i2, value: t },
      };
    }
    return {
      prompt: `À l’aide du tableau (données fictives), calcule l’indice de la variable « ${s.variable} » en ${years[tgt]}, base 100 en ${years[ref]}. ${roundHint(1)}`,
      figure: valueTable(s, years, values),
      ...sesAnswer(rng, f, idx, 1, [
        { v: (values[ref] / values[tgt]) * 100, e: 'methode' },
        { v: idx - 100, e: 'cours' },
        { v: values[tgt] - values[ref] + 100, e: 'methode' },
      ]),
      hints: ['Indice = valeur de l’année ÷ valeur de l’année de référence × 100.', `Année de référence : ${years[ref]} (valeur ${m(num(values[ref], 'fr'))}).`],
      solution: [`${m(`I_{${years[tgt]}} = \\frac{${num(values[tgt], 'fr')}}{${num(values[ref], 'fr')}} \\times 100`)}.`, `${m(`\\approx ${nf(idx, 1)}`)}.`, `Entre ${years[ref]} et ${years[tgt]}, la variable a ${idx >= 100 ? 'augmenté' : 'diminué'} de ${m(`${nf(Math.abs(idx - 100), 1)}\\ \\%`)}.`],
      meta: { kind: 'index', vRef: values[ref], vTgt: values[tgt], value: idx },
    };
  },
});

// ---------------------------------------------------------------- parts, points de pourcentage, TVAM
export const partsEtPoints = defineGenerator({
  id: 'ses-parts-points',
  subject: 'ses',
  skill: SKILL,
  title: 'Parts en % et points de pourcentage',
  formats: ['input', 'mcq'],
  difficulties: ['easy', 'medium', 'hard'],
  targetSec: 90,
  build(rng, d, f) {
    if (d === 'easy') {
      const total = rng.int(200, 2000);
      const part = rng.int(Math.round(total * 0.05), Math.round(total * 0.8));
      const sector = rng.pick(['secteur tertiaire', 'industrie', 'agriculture', 'services marchands']);
      const share = (part / total) * 100;
      return {
        prompt: `Dans le Pays A (données fictives), l’emploi total est de ${m(num(total, 'fr'))} milliers de personnes, dont ${m(num(part, 'fr'))} milliers dans le ${sector === 'industrie' || sector === 'agriculture' ? `secteur « ${sector} »` : sector}. Calcule la part de l’emploi de ce secteur dans l’emploi total, en %. ${roundHint(1)}`,
        ...sesAnswer(
          rng,
          f,
          share,
          1,
          [
            { v: (total / part) * 100, e: 'methode' },
            { v: part / total, e: 'cours' },
            { v: ((total - part) / total) * 100, e: 'lecture' },
          ],
          ' \\%',
        ),
        hints: ['Part (en %) = valeur de la partie ÷ valeur du tout × 100.', `Le tout : ${m(num(total, 'fr'))}.`],
        solution: [`${m(`\\frac{${num(part, 'fr')}}{${num(total, 'fr')}} \\times 100`)}.`, `${m(`\\approx ${nf(share, 1)}\\ \\%`)}.`, `Dans le Pays A, ${m(`${nf(share, 1)}\\ \\%`)} des emplois relèvent de ce secteur (données fictives).`],
        meta: { kind: 'part', part, total, value: share },
      };
    }
    if (d === 'medium') {
      const r1 = rng.int(30, 140) / 10;
      const r2 = rng.int(30, 140) / 10;
      const pts = r2 - r1;
      const [y1, y2] = pickYears(rng);
      return {
        prompt: `Dans le Pays B (données fictives), le taux de chômage est passé de ${m(`${nf(r1)}\\ \\%`)} en ${y1} à ${m(`${nf(r2)}\\ \\%`)} en ${y2}. De combien de points de pourcentage a-t-il varié ? (nombre signé, ${roundHint(1).toLowerCase()})`,
        ...sesAnswer(rng, f, pts, 1, [
          { v: ((r2 - r1) / r1) * 100, e: 'cours' },
          { v: -pts, e: 'calcul' },
          { v: r2 / r1, e: 'cours' },
        ], ' \\text{ pt}'),
        hints: ['La variation d’un taux exprimé en % se mesure en points de pourcentage : on fait une simple différence.', `${m(`${nf(r2)} - ${nf(r1)}`)}.`],
        solution: [`${m(`${nf(r2)} - ${nf(r1)} = ${nf(pts)}`)}.`, `Le taux a ${pts >= 0 ? 'augmenté' : 'baissé'} de ${m(nf(Math.abs(pts)))} point(s) de pourcentage.`, `À ne pas confondre avec le taux de variation du taux (${m(`${nf(((r2 - r1) / r1) * 100)}\\ \\%`)}).`],
        meta: { kind: 'points', r1, r2, value: pts },
      };
    }
    // TVAM
    const n = rng.int(3, 12);
    const v1 = rng.int(100, 900);
    const v2 = Math.round(v1 * (0.7 + rng.next() * 1.0));
    const tvam = ((v2 / v1) ** (1 / n) - 1) * 100;
    const y1 = 2010;
    return {
      prompt: `Le chiffre d’affaires de l’Entreprise B (données fictives) passe de ${m(num(v1, 'fr'))} millions d’euros en ${y1} à ${m(num(v2, 'fr'))} millions d’euros en ${y1 + n}. Calcule le taux de variation annuel moyen, en %. ${roundHint(2)}`,
      ...sesAnswer(
        rng,
        f,
        tvam,
        2,
        [
          { v: ((v2 - v1) / v1) * 100 / n, e: 'cours' },
          { v: ((v2 - v1) / v1) * 100, e: 'lecture' },
          { v: ((v2 / v1) ** (1 / (n + 1)) - 1) * 100, e: 'calcul' },
        ],
        ' \\%',
      ),
      hints: ['TVAM = (CM^(1/n) − 1) × 100, avec CM le coefficient multiplicateur global et n le nombre d’années.', `${m(`n = ${y1 + n} - ${y1} = ${n}`)}.`],
      solution: [`${m(`\\text{CM} = \\frac{${num(v2, 'fr')}}{${num(v1, 'fr')}} \\approx ${nf(v2 / v1, 4)}`)}.`, `${m(`\\text{TVAM} = \\left(\\text{CM}^{1/${n}} - 1\\right) \\times 100`)}.`, `${m(`\\approx ${nf(tvam, 2)}\\ \\%`)} par an en moyenne.`],
      meta: { kind: 'tvam', v1, v2, n, value: tvam },
    };
  },
});

// ---------------------------------------------------------------- write a value as a sentence
export const phraseSES = defineGenerator({
  id: 'ses-phrase',
  subject: 'ses',
  skill: SKILL,
  title: 'Faire une phrase avec une donnée',
  formats: ['mcq'],
  difficulties: ['easy', 'medium', 'hard'],
  targetSec: 60,
  build(rng, d) {
    const s = rng.pick(SERIES);
    const [y1, y2] = pickYears(rng);
    const type = d === 'easy' ? 'tv' : d === 'medium' ? rng.pick(['index', 'cm'] as const) : rng.pick(['points', 'index'] as const);
    let correct: string;
    let wrong: string[];
    let given: string;
    let explanation: string;
    if (type === 'tv') {
      const t = rng.int(-300, 600) / 10;
      given = `Taux de variation de la variable « ${s.variable} » (${s.entity}) entre ${y1} et ${y2} : ${m(`${nf(t)}\\ \\%`)}.`;
      correct = `Selon le document (données fictives), entre ${y1} et ${y2}, la variable « ${s.variable} » de ${s.entity} a ${t >= 0 ? 'augmenté' : 'diminué'} de ${nf(Math.abs(t))} %.`;
      wrong = [
        `Selon le document (données fictives), entre ${y1} et ${y2}, la variable « ${s.variable} » de ${s.entity} a ${t >= 0 ? 'augmenté' : 'diminué'} de ${nf(Math.abs(t))} points de pourcentage.`,
        `Selon le document (données fictives), en ${y2}, la variable « ${s.variable} » de ${s.entity} est de ${nf(Math.abs(t))} %.`,
        `Selon le document (données fictives), entre ${y1} et ${y2}, la variable « ${s.variable} » de ${s.entity} a été multipliée par ${nf(Math.abs(t))}.`,
      ];
      explanation = 'Un taux de variation s’énonce « a augmenté / diminué de … % » entre deux dates, avec la source.';
    } else if (type === 'cm') {
      const cm = rng.int(105, 350) / 100;
      given = `Coefficient multiplicateur de la variable « ${s.variable} » (${s.entity}) entre ${y1} et ${y2} : ${m(nf(cm, 2))}.`;
      correct = `Selon le document (données fictives), la variable « ${s.variable} » de ${s.entity} a été multipliée par ${nf(cm, 2)} entre ${y1} et ${y2}, soit une hausse de ${nf((cm - 1) * 100, 0)} %.`;
      wrong = [
        `Selon le document (données fictives), la variable « ${s.variable} » de ${s.entity} a augmenté de ${nf(cm * 100, 0)} % entre ${y1} et ${y2}.`,
        `Selon le document (données fictives), la variable « ${s.variable} » de ${s.entity} a augmenté de ${nf(cm, 2)} % entre ${y1} et ${y2}.`,
        `Selon le document (données fictives), la variable « ${s.variable} » de ${s.entity} a été multipliée par ${nf((cm - 1) * 100, 0)} entre ${y1} et ${y2}.`,
      ];
      explanation = `Un coefficient multiplicateur ${m('\\text{CM}')} correspond à une hausse de ${m('(\\text{CM} - 1) \\times 100')} %.`;
    } else if (type === 'index') {
      const i = rng.int(60, 250);
      given = `Indice de la variable « ${s.variable} » (${s.entity}) en ${y2}, base 100 en ${y1} : ${m(`${i}`)}.`;
      const up = i >= 100;
      correct = `Selon le document (données fictives), entre ${y1} et ${y2}, la variable « ${s.variable} » de ${s.entity} a ${up ? 'augmenté' : 'diminué'} de ${Math.abs(i - 100)} %.`;
      wrong = [
        `Selon le document (données fictives), entre ${y1} et ${y2}, la variable « ${s.variable} » de ${s.entity} a augmenté de ${i} %.`,
        `Selon le document (données fictives), en ${y2}, la variable « ${s.variable} » de ${s.entity} vaut ${i}.`,
        `Selon le document (données fictives), entre ${y1} et ${y2}, la variable « ${s.variable} » de ${s.entity} a ${up ? 'augmenté' : 'diminué'} de ${Math.abs(i - 100)} points de pourcentage.`,
      ];
      explanation = 'Un indice de 135 (base 100 en année de référence) signifie une hausse de 35 % depuis l’année de référence ; ce n’est pas la valeur de la variable.';
    } else {
      const r1 = rng.int(40, 200) / 10;
      const r2 = r1 + rng.nonZero(-40, 40) / 10;
      const pts = r2 - r1;
      given = `Taux de chômage du Pays B : ${m(`${nf(r1)}\\ \\%`)} en ${y1}, ${m(`${nf(r2)}\\ \\%`)} en ${y2}.`;
      correct = `Selon le document (données fictives), le taux de chômage du Pays B a ${pts >= 0 ? 'augmenté' : 'baissé'} de ${nf(Math.abs(pts))} point${Math.abs(pts) >= 2 ? 's' : ''} de pourcentage entre ${y1} et ${y2}.`;
      wrong = [
        `Selon le document (données fictives), le taux de chômage du Pays B a ${pts >= 0 ? 'augmenté' : 'baissé'} de ${nf(Math.abs(pts))} % entre ${y1} et ${y2}.`,
        `Selon le document (données fictives), le taux de chômage du Pays B a ${pts >= 0 ? 'augmenté' : 'baissé'} de ${nf(Math.abs((pts / r1) * 100))} points de pourcentage entre ${y1} et ${y2}.`,
        `Selon le document (données fictives), le nombre de chômeurs du Pays B a ${pts >= 0 ? 'augmenté' : 'baissé'} de ${nf(Math.abs(pts))} % entre ${y1} et ${y2}.`,
      ];
      explanation = 'La variation d’un taux (en %) se dit en points de pourcentage.';
    }
    return {
      prompt: `${given}\n\nQuelle phrase rédige correctement cette donnée ?`,
      answer: buildMcq(
        rng,
        { text: correct, key: correct },
        wrong.map((w, i) => ({ text: w, key: w, errorType: i === 1 ? 'lecture' : 'cours' })),
        () => {
          throw new Error('ses-phrase: missing distractor');
        },
      ),
      answerDisplay: correct,
      hints: ['Une bonne phrase : source + date(s) + entité + verbe juste (augmenter de… %, être multiplié par…, points de pourcentage…) + unité.', 'Attention aux confusions % / points de %, indice / valeur, coefficient / taux.'],
      solution: [explanation, correct],
      meta: { kind: type },
    };
  },
});

export const SES_CALC_GENERATORS = [tauxVariation, indice100, partsEtPoints, phraseSES];
